import yaml

from yaml.constructor import ConstructorError
from yaml.nodes import MappingNode

try:
    from yaml import CLoader as Loader
except ImportError:
    from yaml import Loader


class UniqueKeyLoader(Loader):
    """UniqueKeyLoader"""

    # pylint: disable=too-many-ancestors

    def construct_mapping(self, node, deep=False):
        """Method ensuring that constructed mapping does not contain duplicate keys."""
        if not isinstance(node, MappingNode):
            raise ConstructorError(None, None,
                                   "expected a mapping node, but found %s" % node.id,
                                   node.start_mark)
        mapping = {}
        self.flatten_mapping(node)
        for key_node, value_node in node.value:
            key = self.construct_object(key_node, deep=deep)
            try:
                hash(key)
            except TypeError as exc:
                raise ConstructorError("while constructing a mapping", node.start_mark,
                                       "found unacceptable key (%s)" % exc, key_node.start_mark)
            # check for duplicate keys
            if key in mapping:
                raise ConstructorError("while constructing a mapping", node.start_mark,
                                       "found duplicate key", key_node.start_mark)
            value = self.construct_object(value_node, deep=deep)
            mapping[key] = value
        return mapping


class ConfigLoader(object):
    """Module reading configuration from yaml file"""
    REQUIRED_SECTIONS = ["ATTENUATORS", "CELLS_ATTENUATION"]

    def __init__(self, config_path):
        self.config_path = config_path

    def load_config(self):
        """
        Load and return configuration from yaml
        :return:
        """
        try:
            with open(self.config_path, 'r') as config_file:
                config = yaml.load(config_file, UniqueKeyLoader)
                self._check_syntax(config)
            return config
        except IOError:
            raise ConfigurationFileNotFound('File does not exist: {}'.format(self.config_path))
        except ConstructorError as e:
            raise WrongSyntaxInConfigurationFile('Found duplicate entries in YAML: {}\n'.format(self.config_path) +
                                                 'Original exception text: {}'.format(str(e)))

    def _check_syntax(self, config):
        found_sections = []
        for section in config:
            found_sections.append(section)
        for required_section in self.REQUIRED_SECTIONS:
            if required_section not in found_sections:
                raise WrongSyntaxInConfigurationFile("Required sections: {}. Check syntax in your config file.".format(self.REQUIRED_SECTIONS))


class ConfigurationFileNotFound(Exception):
    """Exception class"""
    pass


class WrongSyntaxInConfigurationFile(Exception):
    """Exception class"""
    pass
